	[TestMethod]
	public async Task GetBattle_ThrowsException_WhenConnectionThrows()
	{
		// Arrange.
		string fileName = "replay.wotbreplay";
		byte[] fileContent = [1, 2, 3];
		string title = "Test Battle";

		_mockConnection!.UploadReplayAsync(Arg.Any<string>(), fileName, fileContent, title)
			.Returns<Task<string>>(x => throw new Exception("API error"));

		// Act & Assert.
		await Assert.ThrowsExceptionAsync<Exception>(async () =>
		{
			await _repository!.GetBattleAsync(fileName, fileContent, title);
		});
	}
